revoke insert on public.question_teacher_invites from authenticated;
grant insert (question_id, owner_id, invited_email) on public.question_teacher_invites to authenticated;
drop policy "question_teacher_invites_owner_select" on public.question_teacher_invites;
drop policy "question_teacher_invites_invitee_select" on public.question_teacher_invites;
create policy "question_teacher_invites_select" on public.question_teacher_invites for select to authenticated using ((select auth.uid()) = owner_id or (lower(coalesce((select auth.jwt() ->> 'email'), '')) = invited_email and revoked_at is null));
drop policy "question_teacher_invites_invitee_accept" on public.question_teacher_invites;
create policy "question_teacher_invites_invitee_accept" on public.question_teacher_invites for update to authenticated using (lower(coalesce((select auth.jwt() ->> 'email'), '')) = invited_email and accepted_by is null and revoked_at is null) with check (lower(coalesce((select auth.jwt() ->> 'email'), '')) = invited_email and accepted_by = (select auth.uid()) and accepted_at is not null and revoked_at is null);
drop policy "questions_owner_all" on public.questions;
create policy "questions_select_owner_or_shared_teacher" on public.questions for select to authenticated using (owner_id = (select auth.uid()) or exists (select 1 from public.question_teacher_invites invite where invite.question_id = questions.id and invite.owner_id = questions.owner_id and invite.accepted_by = (select auth.uid()) and invite.revoked_at is null));
create policy "questions_owner_insert" on public.questions for insert to authenticated with check (owner_id = (select auth.uid()));
create policy "questions_owner_update" on public.questions for update to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy "questions_owner_delete" on public.questions for delete to authenticated using (owner_id = (select auth.uid()));
drop policy "question_solutions_owner_select" on public.question_solutions;
drop policy "question_solutions_shared_teacher_select" on public.question_solutions;
create policy "question_solutions_select_owner_or_shared_teacher" on public.question_solutions for select to authenticated using (owner_id = (select auth.uid()) or exists (select 1 from public.question_teacher_invites invite where invite.question_id = question_solutions.question_id and invite.owner_id = question_solutions.owner_id and invite.accepted_by = (select auth.uid()) and invite.revoked_at is null));
drop policy "question_solution_reviews_owner_select" on public.question_solution_reviews;
drop policy "question_solution_reviews_shared_teacher_select" on public.question_solution_reviews;
create policy "question_solution_reviews_select_owner_or_reviewer" on public.question_solution_reviews for select to authenticated using (owner_id = (select auth.uid()) or (reviewer_id = (select auth.uid()) and exists (select 1 from public.question_solutions solution join public.question_teacher_invites invite on invite.question_id = solution.question_id and invite.owner_id = solution.owner_id where solution.id = question_solution_reviews.solution_id and invite.owner_id = question_solution_reviews.owner_id and invite.accepted_by = (select auth.uid()) and invite.revoked_at is null)));
drop policy "question_solution_reviews_owner_insert" on public.question_solution_reviews;
drop policy "question_solution_reviews_teacher_insert" on public.question_solution_reviews;
create policy "question_solution_reviews_owner_or_teacher_insert" on public.question_solution_reviews for insert to authenticated with check (reviewer_id = (select auth.uid()) and (owner_id = (select auth.uid()) or (owner_id <> (select auth.uid()) and exists (select 1 from public.question_solutions solution join public.question_teacher_invites invite on invite.question_id = solution.question_id and invite.owner_id = solution.owner_id where solution.id = question_solution_reviews.solution_id and invite.owner_id = question_solution_reviews.owner_id and invite.accepted_by = (select auth.uid()) and invite.revoked_at is null))));
